namespace NovaHarvest.Core.Systems; public sealed class Inventory { readonly Dictionary<string, int> _items = new(); public IReadOnlyDictionary<string, int> Items => _items; public int GetAmount(string id) => _items.TryGetValue(id, out var n) ? n : 0; public void Add(string id, int amount = 1) { if (string.IsNullOrWhiteSpace(id)) throw new ArgumentException("Item ID inválido.", nameof(id)); if (amount <= 0) throw new ArgumentOutOfRangeException(nameof(amount)); _items[id] = GetAmount(id) + amount; } public bool Remove(string id, int amount = 1) { if (amount <= 0 || GetAmount(id) < amount) return false; var left = GetAmount(id) - amount; if (left == 0) _items.Remove(id); else _items[id] = left; return true; } public bool Has(string id, int amount = 1) => amount > 0 && GetAmount(id) >= amount; }
